// ***************
// Filename: watchdog_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of watchdog: joins the register map
//   watchdog_regs (modport regs) and the logic watchdog (modport core). cfg_*
//   go from the register map to the logic (register values, _wr write pulses,
//   _rd read pulses), sts_* come back (values read, _set / _clr hardware set
//   / clear pulses). A logic block ties every sts_* member it does not use to
//   0. Generated by ip/scripts/regmap_gen.py from watchdog_regs.json: edit
//   the JSON and regenerate.
// Date: 2026-10-16
interface watchdog_regs_if ();
  logic [3-1:0] sts_ctrl;
  logic [3-1:0] cfg_ctrl;
  logic cfg_ctrl_wr;
  logic [32-1:0] cfg_timeout;
  logic cfg_timeout_wr;
  logic [32-1:0] cfg_prescale;
  logic cfg_prescale_wr;
  logic [32-1:0] cfg_pretimeout;
  logic cfg_pretimeout_wr;
  logic [32-1:0] cfg_window_open;
  logic cfg_window_open_wr;
  logic [32-1:0] cfg_kick;
  logic cfg_kick_wr;
  logic [4-1:0] sts_status;
  logic [4-1:0] cfg_status;
  logic cfg_status_wr;
  logic [32-1:0] sts_count;

  modport regs (output cfg_ctrl, cfg_ctrl_wr, cfg_timeout, cfg_timeout_wr, cfg_prescale, cfg_prescale_wr,
    cfg_pretimeout, cfg_pretimeout_wr, cfg_window_open, cfg_window_open_wr, cfg_kick, cfg_kick_wr, cfg_status,
    cfg_status_wr, input sts_ctrl, sts_status, sts_count);
  modport core (output sts_ctrl, sts_status, sts_count, input cfg_ctrl, cfg_ctrl_wr, cfg_timeout,
    cfg_timeout_wr, cfg_prescale, cfg_prescale_wr, cfg_pretimeout, cfg_pretimeout_wr, cfg_window_open,
    cfg_window_open_wr, cfg_kick, cfg_kick_wr, cfg_status, cfg_status_wr);
  modport monitor (input cfg_ctrl, cfg_ctrl_wr, cfg_timeout, cfg_timeout_wr, cfg_prescale, cfg_prescale_wr,
    cfg_pretimeout, cfg_pretimeout_wr, cfg_window_open, cfg_window_open_wr, cfg_kick, cfg_kick_wr, cfg_status,
    cfg_status_wr, sts_ctrl, sts_status, sts_count);
endinterface
